func:
var on = (msg.payload === 1 || msg.payload === true);
var was = flow.get('sp_enabled') === true;
flow.set('sp_enabled', on);

if (on && !was) {
    // Fresh enable clears any failed-probe lockout
    var st = flow.get('sp_st');
    if (st && typeof st === 'object') {
        st.backoffMs = 300000;
        st.backoffUntil = 0;
        st.vocAtFail = 0;
        flow.set('sp_st', st);
    }
}

node.status({
    fill: on ? 'green' : 'grey',
    shape: 'dot',
    text: on ? 'ENABLED' : 'DISABLED'
});
return { payload: 'save' };

var val = Number(msg.payload);
if (!isFinite(val) || val < 100 || val > 2500) return null;
flow.set('sp_p_rated', val);
node.status({ fill: 'blue', shape: 'dot', text: val + 'W cap' });
return { payload: 'save' };

// Panel open-circuit voltage when the charger is idle; Vmp when producing.
// Change-only signal: last-known-good, only used as a daylight gate.
var v = Number(msg.payload);
if (!isFinite(v) || v < 0 || v > 150) return null;
flow.set('sp_voc6', { v: v, ts: Date.now() });
node.status({ fill: v > 55 ? 'yellow' : 'grey', shape: 'dot', text: v.toFixed(1) + ' V' });
return null;

var v = Number(msg.payload);
if (!isFinite(v) || v < 0 || v > 150) return null;
flow.set('sp_voc7', { v: v, ts: Date.now() });
node.status({ fill: v > 55 ? 'yellow' : 'grey', shape: 'dot', text: v.toFixed(1) + ' V' });
return null;

// Jitters ~1/s while producing — doubles as this charger's liveness
// heartbeat for the capacity capture.
var w = Number(msg.payload);
if (!isFinite(w) || w < 0 || w > 3000) return null;
flow.set('sp_y6', { v: w, ts: Date.now() });
node.status({ fill: w > 5 ? 'yellow' : 'grey', shape: 'dot', text: w.toFixed(1) + ' W' });
return null;

var w = Number(msg.payload);
if (!isFinite(w) || w < 0 || w > 3000) return null;
flow.set('sp_y7', { v: w, ts: Date.now() });
node.status({ fill: w > 5 ? 'yellow' : 'grey', shape: 'dot', text: w.toFixed(1) + ' W' });
return null;

// 2 = tracker active (unthrottled): the charger's output IS its capacity.
// Change-only enum — last-known-good by design.
var m = Number(msg.payload);
if (!isFinite(m)) return null;
flow.set('sp_m6', { v: m, ts: Date.now() });
var names = { 0: 'off', 1: 'throttled', 2: 'unthrottled (MPPT)' };
node.status({ fill: m === 2 ? 'green' : 'grey', shape: 'dot', text: names[m] || ('mode ' + m) });
return null;

var m = Number(msg.payload);
if (!isFinite(m)) return null;
flow.set('sp_m7', { v: m, ts: Date.now() });
var names = { 0: 'off', 1: 'throttled', 2: 'unthrottled (MPPT)' };
node.status({ fill: m === 2 ? 'green' : 'grey', shape: 'dot', text: names[m] || ('mode ' + m) });
return null;

// Jitters ~1/s (measured 57/min at steady load) — this timestamp is also
// the liveness heartbeat for the whole com.victronenergy.system service
// (SOC and battery power are change-only and can be silent for minutes).
var w = Number(msg.payload);
if (!isFinite(w) || w < 0 || w > 20000) return null;
var now = Date.now();
flow.set('sp_ac_load', { v: w, ts: now });

// Time-based rolling window (not sample-count-based: the update rate
// is not a fixed 1 Hz, so counting samples would give an unknown window).
var s = flow.get('sp_load_window') || [];
s.push({ t: now, w: w });
var cutoff = now - 60000;
while (s.length && s[0].t < cutoff) s.shift();
if (s.length > 300) s.splice(0, s.length - 300);
flow.set('sp_load_window', s);

var sum = 0;
for (var i = 0; i < s.length; i++) sum += s[i].w;
var avg = sum / s.length;
flow.set('sp_ac_load_avg', { v: avg, ts: now });

node.status({
    fill: 'blue', shape: 'dot',
    text: w.toFixed(0) + 'W now, ' + avg.toFixed(0) + 'W avg (' + s.length + ' samples)'
});
return null;

// Change-only (hi-res 0.01% steps can hold for minutes at low current):
// last-known-good, validity comes from the system-service heartbeat.
var pct = Number(msg.payload);
if (!isFinite(pct) || pct < 0 || pct > 100) return null;
flow.set('sp_soc', { v: pct, ts: Date.now() });
var fill = pct > 50 ? 'green' : (pct > 30 ? 'yellow' : 'red');
node.status({ fill: fill, shape: 'dot', text: pct.toFixed(1) + ' %' });
return null;

// + = charging, - = discharging. This is the primary truth signal:
// 'no cycling in storage' means this stays near zero.
// Change-only (measured: silent for minutes at a steady -17W idle) —
// last-known-good, validity comes from the system-service heartbeat.
var w = Number(msg.payload);
if (!isFinite(w) || Math.abs(w) > 30000) return null;
flow.set('sp_batt_power', { v: w, ts: Date.now() });
node.status({
    fill: w < -50 ? 'yellow' : 'green',
    shape: 'dot',
    text: (w >= 0 ? '+' : '') + w.toFixed(0) + ' W' + (w < -50 ? ' (discharging)' : '')
});
return null;

// 0 = AC-in 1 (shore), 1 = AC-in 2, 240 = disconnected/inverting.
// Lets the engine verify its commands actually took effect and detect
// an absent shore connection before probing. Change-only enum —
// last-known-good, validity comes from the vebus heartbeat (AC Out Power).
var v = Number(msg.payload);
if (!isFinite(v)) return null;
flow.set('sp_active_input', { v: v, ts: Date.now() });
var names = { 0: 'AC-in 1', 1: 'AC-in 2', 240: 'inverting' };
node.status({
    fill: v === 240 ? 'yellow' : 'green',
    shape: 'dot',
    text: names[v] || ('code ' + v)
});
return null;

// Jitters ~1/s whether on shore or inverting (loads are always drawing) —
// this timestamp is the liveness heartbeat for the vebus service, whose
// interesting paths (ActiveInput) are change-only enums.
var w = Number(msg.payload);
if (!isFinite(w) || w < -20000 || w > 20000) return null;
flow.set('sp_ac_out', { v: w, ts: Date.now() });
node.status({ fill: 'blue', shape: 'dot', text: w.toFixed(0) + ' W out' });
return null;

// Compared against the BMS CVL: while battV > CVL the MPPTs back off to
// zero (absorption tail), so probing is pointless and blocked.
var v = Number(msg.payload);
if (!isFinite(v) || v < 20 || v > 80) return null;
flow.set('sp_batt_v', { v: v, ts: Date.now() });
var cvl = flow.get('sp_cvl');
var above = cvl && typeof cvl.v === 'number' && v > cvl.v + 0.05;
node.status({ fill: above ? 'yellow' : 'green', shape: 'dot', text: v.toFixed(2) + ' V' + (above ? ' > CVL' : '') });
return null;

// The slider/EQ TARGET the system converges to (dbus-recbms >= 1.3.0:
// /Info/MaxChargeVoltage is the Quattro's lead-LOWERED command, not the
// target). Changes only when the slider moves or EQ starts/ends.
var v = Number(msg.payload);
if (!isFinite(v) || v < 20 || v > 80) return null;
flow.set('sp_cvl', { v: v, ts: Date.now() });
node.status({ fill: 'blue', shape: 'dot', text: v.toFixed(2) + ' V' });
return null;

// === Solar Priority — Decision Engine v4.2 ===
//
// Goal: while plugged in and in storage (battery held at ~60% by the Max
// Charge slider), power AC loads from solar whenever the panels can carry
// them — with as close to zero energy cycled through the battery as possible.
//
// States: shore -> probe (90s MPPT ramp) -> solar -> shore
//         shore -> burndown (pack above target, or harvest) -> solar | probe | shore
//         solar/burndown -> suspend (heater on shore) -> resumed
//
// v3 principles (built against live bus measurements, 2026-08-18):
//  - Capacity is MEASURED, not modelled: /MppOperationMode == 2 means the
//    charger is unthrottled, so its /Yield/Power IS its current capacity.
//    Captured per charger, trusted 15 min, faded to zero by 90 min. The
//    chargers bulk-charge unthrottled for hours most mornings, and a failed
//    probe is itself a measurement, so the estimate is usually evidence.
//  - Victron services publish on CHANGE only (battery power / SOC / modes /
//    ActiveInput can be silent for minutes-hours). Silence = unchanged:
//    values are last-known-good; service LIVENESS is tracked via paths
//    that provably jitter ~1/s (system: AC consumption, vebus: AC out,
//    each MPPT: its PV power while producing).
//  - Battery power is the primary truth signal: solar mode is only kept
//    while the pack is not discharging. Charging is allowed — surplus
//    charges the pack until DVCC/CVL caps it at the storage target.
//  - Safety exits to shore ignore cooldown; cooldown/backoff only gate
//    shore -> probe. Failed probes back off 5m -> 60m; released early by
//    capacity evidence (measured or modelled) clearing the bar, a >=30 min
//    stable solar stint, or a re-enable.
//  - v3.4: adaptive per-MPPT panel model — while a charger is THROTTLED
//    (battery at CVL) but passing even a trickle, the panel voltage's
//    distance below its open-circuit voltage reveals how much current the
//    panel could source (single-diode I-V curve), so capacity is estimated
//    continuously without probing; unthrottled operation (incl. every
//    probe) calibrates the model. Probes are gated on the charger being
//    quiet so a running Prefer-Renewable charge cycle is never reset, and
//    est/explore are gated on the MPPTs being awake (night) and Voc having
//    plateaued (dawn).
//  - v3.5: BOOST-ASSISTED PROBES. In the steady state the pack sits AT the
//    target voltage, which is also the MPPT ceiling — so a probe drops
//    shore with ~0V of margin and the chargers ramp glacially (measured
//    2026-08-20: 25W at 60s into a probe, while the same array did 600W
//    in ~60s under a 0.30V boost). Every probe now requests the boost for
//    its ramp and releases it on exit. On handover the pack briefly holds
//    boost energy ABOVE the target and the MPPTs throttle until it drains
//    into the loads; that drain and a 90s settle window are exempt from
//    the deficit/surge exits (SOC and fault exits stay live).
//  - v3.6: AVERAGED RECONNECT. Near the target the MPPTs regulate VOLTAGE
//    with a margin-limited response — their output hunts around the demand
//    and battery power flips sign even with ample capacity (measured
//    2026-08-20: 1W from a 350W-capable array at 0.01V of margin). The
//    deficit exit therefore judges the rolling MEAN of battery power over
//    DEFICIT_AVG_MS; only the 400W surge exit still acts on instantaneous
//    readings.
//  - v4.0: HARVEST-AND-BURN — when capacity < load, solar is no longer
//    wasted: on shore the lead band (target - 0.15V) fills from the sun,
//    and once full (battV within 0.02V of target, charger quiet, daylight)
//    burn-down feeds that stored solar into the loads, then the sun
//    refills. Re-armed only by a NON-shore-fed refill (PV must roughly
//    match the charge power during the climb), so shore energy is never
//    round-tripped through the inverter and nothing arms at night.
//    ~1.2 kWh per burn; ~10-15 FCE/year — negligible NMC wear.
//  - v4.0: SUSPEND — a heater-class load (>= 1kW for 3s) reconnects shore
//    from solar/burn-down with no cooldown and no backoff, and the flow
//    resumes the prior state ~10s after the load returns to its
//    pre-suspend average (+200W). Capped at 20 min, after which it
//    becomes a normal shore stay. The probe's big-load kill now judges
//    the 60s load average too (4s flickers killed two probes 2026-08-20).
//  - v4.1: CEILING-STALL BURN. Observed 2026-08-20 12:30 PT: solar mode
//    refills the band, the pack parks AT the target, the MPPTs sit at
//    zero margin and carry 2-37W of a 300W load, the averaged deficit
//    trips, shore comes back, backoff, boosted probe, repeat — a 9-min
//    loop that never re-arms harvest (the refill tracker needs battV to
//    reach target - 0.10V, and the deficit exit fires at ~target - 0.03V).
//    A solar-mode deficit with the band still full (battV within
//    STALL_BURN_MIN_V of the target, daylight, shore present) is now a
//    burn-down, not a shore exit: the loads open margin under the
//    chargers, the calm handover returns to solar, and the bottom exit
//    still falls back to probe/shore if the sun really has gone.
//  - v4.2: LEAD VERIFICATION. dbus-recbms >= 1.4.0 checks that systemcalc
//    really applies the solar offset (it is silently ignored below GX
//    access level Superuser) and publishes /RecBms/LeadFault (text) and
//    /RecBms/SolarLead (volts in force). While the lead is 0 there is no
//    band under the target to harvest, so harvest-and-burn is disabled;
//    the fault text is raised via node.error() by 'Notify Lead Fault'.
//  - The desired IgnoreAcIn1 value is re-asserted every 30s while enabled.
//  - /Ac/ActiveIn/ActiveInput feedback detects an ineffective command
//    (FAULT lockout) and an absent shore connection (no probe = no fallback).

// ---- Tunables ----
var SOLAR_MARGIN      = 1.2;      // capacity must exceed avg load by 20%
var MIN_EST_W         = 100;      // never probe for less than this
var READY_MS          = 30000;    // probe conditions must hold this long
var RAMP_MS           = 90000;    // probe ramp: MPPTs take ~40s to wake
                                  //   after the shore drop (measured), then
                                  //   ~20s to full power — 90s is safe
var EVAL_MS           = 15000;    // averaging window at the end of the ramp
var DISCHARGE_TOL_W   = 50;       // battery discharge below this = not cycling
var LOAD_EXCEED_MS    = 15000;    // sustained moderate deficit before exit
var SOLAR_SETTLE_MS   = 90000;    // deficit exit is deaf this long after
                                  //   solar entry: the handover first
                                  //   drains the boost surplus, then the
                                  //   MPPTs re-ramp from a tiny margin (v3.5)
var DEFICIT_AVG_MS    = 90000;    // the deficit exit judges the rolling MEAN
                                  //   of battery power over this window: at
                                  //   the ceiling the MPPTs throttle-hunt
                                  //   around the demand, so instantaneous
                                  //   sign flips are normal even with ample
                                  //   capacity (v3.6)
var SURGE_W           = 400;      // battery discharge that counts as a big load
var SURGE_MS          = 3000;     // sustained surge before immediate exit
var COOLDOWN_MS       = 300000;   // min time between transitions (5 min)
var BACKOFF_MAX_MS    = 3600000;  // failed-probe backoff cap (60 min)
var STABLE_MS         = 1800000;  // solar stint >= 30 min resets backoff
var MIN_SOC           = 40;       // never probe below this SOC
var SOC_EMERGENCY     = 30;       // immediate shore + 1h lockout
var SOC_DRIFT_MAX     = 2;        // % below solar-entry SOC -> exit
var HB_STALE_MS       = 20000;    // service heartbeat older than this = down
var ASSERT_MS         = 30000;    // re-assert command interval (enabled only)
var FEEDBACK_GRACE_MS = 90000;    // time allowed for ActiveInput to match
// Capacity estimator
var CAP_SMOOTH        = 0.3;      // blend of a new capture into a <60s-old one
var CAP_FRESH_MS      = 900000;   // capture fully trusted for 15 min
var CAP_ZERO_MS       = 5400000;  // and faded to zero by 90 min
var VOC_DAY_V         = 55;       // max panel Voc below this = night, est 0
var VOC_EXPLORE_V     = 65;       // strong daylight: allows a first probe
                                  //   when no capacity measurement exists
var CVL_MARGIN_V      = 0.05;     // battV above CVL by more than this =
                                  //   MPPTs physically cannot produce
                                  //   (absorption tail) — never probe
var WAKE_MS           = 60000;    // MPPTs must be tracking by this point of
                                  //   the ramp (measured wake ~40s) or the
                                  //   probe is aborted
// Burn-down (pack above target: feed loads from the surplus, no sun needed)
var BURN_EXIT_DROP_V  = 0.15;     // exit when battV (under load) falls this
                                  //   far below CVL — well past the ~0.08V
                                  //   IR sag measured at 500W, so the exit
                                  //   cannot flap on load-induced sag
var BURN_EXIT_MS      = 30000;    // sustained before leaving burn-down
var BURN_CALM_MS      = 15000;    // batt no longer discharging this long in
                                  //   burn-down = solar took over -> solar
var SURPLUS_QUIET_W   = 100;      // battV above CVL only counts as surplus
                                  //   while the charger is quiet (<= this W):
                                  //   the Quattro overshoots the CVL while
                                  //   absorbing (observed 56.78V @ +471W)
// Capacity measurement via the BMS driver's solar boost. Raising ONLY the
// MPPTs above the Quattro's regulation point makes them run unthrottled
// (MppOperationMode 2) — the state where their output IS their capacity — so
// the array is measured WITHOUT dropping shore power. dbus-recbms owns the
// request, clamps it against live cell data and expires it by itself, so
// nothing here can leave the bank charging high.
var BOOST_V           = 0.30;     // requested offset (= the driver's cap;
                                  //   the Quattro's absorb overshoot eats
                                  //   margin, so ask for the maximum)
var BOOST_INTERVAL_MS = 900000;   // refresh a known capacity every 15 min
var BOOST_RETRY_MS    = 180000;   // ...but retry sooner while nothing is known
                                  //    (the driver's own boost lasts 120s, so
                                  //     this still leaves a gap between runs)
var BURN_REARM_V      = 0.25;     // after a completed burn-down, re-arm only
                                  //   on a CVL change or battV this far above
                                  //   CVL (real overcharge — the Quattro's
                                  //   post-shore overshoot stays under it)
// Harvest-and-burn (v4.0): when capacity < load, solar still fills the
// lead band below the target on shore; once full, burn it into the loads.
var HARVEST_ARM_V     = 0.02;     // battV within this of target = band full
var REFILL_RESET_V    = 0.10;     // must dip this far under target (and
                                  //   climb back on sun) to re-arm harvest
var HARVEST_MIN_EVID  = 100;      // bootstrap arm (fresh deploy with the
                                  //   band already full) needs this much
                                  //   capacity evidence (W)
var STALL_BURN_MIN_V  = 0.05;     // solar-mode deficit with battV at least
                                  //   this close to the target = ceiling
                                  //   stall -> burn-down, not shore (v4.1);
                                  //   leaves >= 0.10V of band to burn
// Suspend (v4.0): heater-class loads go to shore instantly and briefly
var SUSPEND_LOAD_W    = 1000;     // load that always belongs on shore
var SUSPEND_MS        = 3000;     // confirm before suspending
var SUSPEND_MAX_MS    = 1200000;  // cap (20 min); then a normal shore stay
var RESUME_DELTA_W    = 200;      // load back within this of the
                                  //   pre-suspend average = resume
var RESUME_MS         = 10000;    // resume confirm
// Adaptive panel model (per MPPT): estimates instantaneous capacity while
// the charger is THROTTLED, from how far the panel voltage is pulled below
// open-circuit voltage at the current draw. Single-diode approximation:
//   I = Isc * (1 - exp((V - Voc)/a))  ->  Isc = (P/V) / ratio
//   capacity ~= kff * Voc * Isc       (kff calibrated whenever mode == 2)
// Near Voc the exponential is razor thin, so shallow-draw estimates are
// treated as LOWER BOUNDS (good enough to justify a probe, never to skip
// one); deep-draw estimates (ratio >= MDL_RATIO_CONF) are trusted, so a
// confidently dim reading suppresses blind exploratory probes.
var MDL_A_V        = 3.5;      // effective string thermal voltage (~102
                               //   cells x n*Vt); errors fold into kff
var MDL_VOC_IDLE_W = 3;        // charger output below this = panel at Voc
var MDL_VOC_TAU_MS = 600000;   // Voc reference EMA time constant (10 min)
var MDL_MIN_W      = 10;       // min draw for a throttled estimate
var MDL_CAL_MIN_W  = 30;       // min unthrottled power for a kff calibration
var MDL_KFF_DEF    = 0.78;     // fill-factor-ish default until calibrated
var MDL_KFF_ALPHA  = 0.05;     // calibration EMA blend per tick
var MDL_RATIO_MIN  = 0.02;     // ratio floor: below it, pure lower bound
var MDL_RATIO_CONF = 0.3;      // ratio above this = trusted estimate
var MDL_MAX_MULT   = 20;       // lower-bound cap: capacity <= draw x this
var MDL_FRESH_MS   = 300000;   // an estimate lives this long (5 min)
var MDL_SHARE6     = 0.35;     // array share per charger for scaling one
var MDL_SHARE7     = 0.65;     //   confident reading to the whole plant
                               //   (7-day peaks: 604W + 1148W)
var VOC_RISE_V     = 1.0;      // Voc rose more than this within the 10-min
                               //   reference window = dawn ramp, no explore

var now = Date.now();

function val(key) {
    var o = flow.get(key);
    return (o && typeof o.v === 'number' && isFinite(o.v)) ? o : null;
}

var enabled = flow.get('sp_enabled') === true;
var soc     = val('sp_soc');
var batt    = val('sp_batt_power');   // W: + charging, - discharging
var loadNow = val('sp_ac_load');
var loadAvg = val('sp_ac_load_avg');
var feed    = val('sp_active_input'); // 0=ACin1, 1=ACin2, 240=inverting
var acOut   = val('sp_ac_out');       // vebus liveness heartbeat
var voc6 = val('sp_voc6'), voc7 = val('sp_voc7');
var y6   = val('sp_y6'),   y7   = val('sp_y7');
var m6   = val('sp_m6'),   m7   = val('sp_m7');
var battV = val('sp_batt_v');     // battery bus voltage
var cvl   = val('sp_cvl');        // charge TARGET (slider+EQ; solar lead excluded)
// dbus-recbms solar boost feedback
var boostAct = val('sp_boost_active');
var boostWin = val('sp_boost_window');
var boostEff = val('sp_boost_eff');
var boosting = boostAct !== null && boostAct.v === 1;
// Solar lead actually in force (dbus-recbms >= 1.4.0). Absent on an older
// driver -> assume the configured lead is in force (v4.1 behavior).
var leadV = val('sp_lead');
var leadOn = leadV === null || leadV.v > 0.005;
var leadFault = flow.get('sp_lead_fault') || '';
var windowOpen = boostWin !== null && boostWin.v === 1;

var pRated = flow.get('sp_p_rated');
if (typeof pRated !== 'number' || !isFinite(pRated) || pRated < 100 || pRated > 2500) pRated = 1800;

var st = flow.get('sp_st');
if (!st || typeof st !== 'object' || !st.state) {
    st = {
        state: 'shore', desired: 0, lastSent: null, lastAssert: 0,
        lastTransition: now, probeStart: 0, probeEst: 0, evalPv: [], evalBatt: [],
        readySince: 0, loadExceedStart: 0, surgeStart: 0,
        backoffMs: COOLDOWN_MS, backoffUntil: 0,
        socEntry: 0, solarSince: 0, cap6: null, cap7: null,
        burnReadySince: 0, burnExitStart: 0, burnCalmStart: 0, burnDoneCvl: null,
        refillReady: null, refillShoreFed: false, harvestSince: 0,
        suspendTrigStart: 0, suspendStart: 0, suspendBase: 0, resumeStart: 0,
        suspendPrev: null
    };
}

// ---- Service liveness ----
var sysAlive   = loadNow !== null && (now - loadNow.ts) < HB_STALE_MS;
var vebusAlive = acOut   !== null && (now - acOut.ts)   < HB_STALE_MS;

// ---- Rolling battery-power mean (v3.6) ----
// batt is last-known-good on a change-only bus, so sampling it once per
// tick gives a true time-weighted window. Solar-mode health is judged on
// this mean, never on the instantaneous sign (MPPT throttle-hunting).
if (batt !== null) {
    var bw = st.battWin || [];
    bw.push({ t: now, w: batt.v });
    while (bw.length && bw[0].t < now - DEFICIT_AVG_MS) bw.shift();
    if (bw.length > 150) bw.splice(0, bw.length - 150);
    st.battWin = bw;
}
var battMean = null;
if (st.battWin && st.battWin.length >= 5) {
    var bsum = 0;
    for (var bi = 0; bi < st.battWin.length; bi++) bsum += st.battWin[bi].w;
    battMean = bsum / st.battWin.length;
}

// ---- Capacity capture: an unthrottled MPPT's output IS its capacity ----
function capture(cap, mode, yld) {
    if (!mode || mode.v !== 2) return cap;                 // throttled/off/unknown
    if (!yld || (now - yld.ts) >= HB_STALE_MS) return cap; // charger must be live
    var w = (cap && (now - cap.ts) < 60000)
        ? cap.w * (1 - CAP_SMOOTH) + yld.v * CAP_SMOOTH
        : yld.v;
    return { w: w, ts: now };
}
// While a boost is ramping the chargers are already in mode 2 but still
// climbing, so an early sample would be recorded as capacity and drag the
// estimate down. The driver publishes WindowOpen for exactly this: sample
// only once it says the array has settled.
if (!boosting || windowOpen) {
    st.cap6 = capture(st.cap6, m6, y6);
    st.cap7 = capture(st.cap7, m7, y7);
}

function faded(cap) {
    if (!cap) return 0;
    var age = now - cap.ts;
    if (age <= CAP_FRESH_MS) return cap.w;
