// Runs every tick, per charger. Voc reference tracks temperature drift from
// idle moments; throttled draw + panel voltage give an Isc estimate; mode 2
// (unthrottled — every probe, every free-running stretch) calibrates kff.
// Not persisted: voc re-learns within minutes, kff within one calibration.
if (!st.mdl6) st.mdl6 = { voc: null, vocTs: 0, kff: MDL_KFF_DEF, est: null };
