function modelTick(mdl, pv, yld, mode) {
    var v = pv ? pv.v : null;
    // Idle detection uses the yield VALUE, not freshness: a charger sitting
    // at 0W publishes once and goes silent (change-only bus).
    if (v !== null && v > VOC_DAY_V && yld !== null && yld.v < MDL_VOC_IDLE_W) {
        if (mdl.voc === null) { mdl.voc = v; }
        else {
            var dt = Math.min(now - mdl.vocTs, 60000);
            mdl.voc += (v - mdl.voc) * Math.min(1, dt / MDL_VOC_TAU_MS);
