// see the same sky. Used only to recognize a confirmed-dim day.
var plantConf = null;
if (me6 && !me6.lb) plantConf = me6.w / MDL_SHARE6;
if (me7 && !me7.lb) plantConf = Math.max(plantConf || 0, me7.w / MDL_SHARE7);

var pvNow    = (y6 ? y6.v : 0) + (y7 ? y7.v : 0);
var capSum   = faded(st.cap6) + faded(st.cap7);
