var transition = null;
var boostMsg = null;
var statusFill = 'grey', statusText = '';

function toShore(reason) {
    st.desired = 0;
    st.state = 'shore';
    st.lastTransition = now;
    st.readySince = 0;
    st.loadExceedStart = 0;
    st.surgeStart = 0;
    st.probeStart = 0;
    st.evalPv = [];
    st.evalBatt = [];
    st.burnReadySince = 0;
    st.burnExitStart = 0;
    st.burnCalmStart = 0;
    st.harvestSince = 0;
    st.suspendTrigStart = 0;
    st.resumeStart = 0;
