    statusText = transition;
}

function escalateBackoff() {
    st.backoffUntil = now + st.backoffMs;
    st.backoffMs = Math.min(st.backoffMs * 2, BACKOFF_MAX_MS);
}

function lockout() {
    st.backoffMs = BACKOFF_MAX_MS;
    st.backoffUntil = now + BACKOFF_MAX_MS;
}

var missing = [];
if (soc === null)  missing.push('SOC');
if (batt === null) missing.push('Batt');
if (loadNow === null || loadAvg === null) missing.push('Load');
if (feed === null) missing.push('ActiveIn');
if (!sysAlive)   missing.push('system-hb');
if (!vebusAlive) missing.push('vebus-hb');

if (!enabled) {
    if (st.state !== 'shore') toShore('disabled');
    else statusText = 'DISABLED';
    statusFill = 'grey';

} else if (missing.length) {
    if (st.state !== 'shore') toShore('no data: ' + missing.join(','));
    else statusText = 'No data: ' + missing.join(', ');
    statusFill = 'red';

} else if (soc.v < SOC_EMERGENCY && st.state !== 'shore') {
