            st.suspendPrev = 'burndown';
            st.desired = 0;
            st.suspendStart = now;
            st.lastTransition = now;
            st.suspendTrigStart = 0;
            st.resumeStart = 0;
            boostMsg = { payload: 0 };
            transition = '-> SUSPEND (load ' + loadNow.v.toFixed(0) + 'W, base ' +
