                           battV.v <= cvl.v - BURN_EXIT_DROP_V;
            if (burnDone) { if (!st.burnExitStart) st.burnExitStart = now; }
            else st.burnExitStart = 0;

            if (st.burnCalmStart && now - st.burnCalmStart >= BURN_CALM_MS) {
