                st.socEntry = soc.v;
                st.solarSince = now;
                st.lastTransition = now;
                st.loadExceedStart = 0;
                st.surgeStart = 0;
                st.burnExitStart = 0;
                st.burnCalmStart = 0;
                st.backoffMs = COOLDOWN_MS;
                st.backoffUntil = 0;
                transition = '-> SOLAR (burn-down handover, PV ' + pvNow.toFixed(0) + 'W)';
                statusFill = 'green';
                statusText = transition;

