                    st.evalBatt = [];
                    st.lastTransition = now;
                    st.surgeStart = 0;
                    st.burnExitStart = 0;
                    st.burnCalmStart = 0;
                    st.lastBoostTs = now;
                    boostMsg = { payload: BOOST_V };   // probe assist (v3.5)
                    transition = '-> PROBE (after burn-down, est ' + est.toFixed(0) + 'W)';
                    statusFill = 'yellow';
                    statusText = transition;
                } else {
                    toShore('burn-down complete (batt ' + battV.v.toFixed(2) + 'V)');
                    statusFill = 'blue';
                }

            } else {
                statusFill = 'green';
                statusText = 'BURN | batt ' + batt.v.toFixed(0) + 'W, ' +
                    (battV !== null ? battV.v.toFixed(2) : '?') + 'V -> ' +
                    (cvl !== null ? (cvl.v - BURN_EXIT_DROP_V).toFixed(2) : '?') +
                    'V, PV ' + pvNow.toFixed(0) + 'W load ' + loadNow.v.toFixed(0) + 'W SOC ' + soc.v.toFixed(1) + '%';
            }
        }

    } else if (st.state === 'suspend') {
        // Shore is deliberately carrying a heater-class load. Resume the
        // prior state the moment the load returns to its pre-suspend
        // average; a suspend older than SUSPEND_MAX_MS becomes a normal
        // shore stay (cooldown applies again). Emergency-SOC (global),
        // disable and missing-data all still exit via toShore.
        if (now - st.suspendStart >= SUSPEND_MAX_MS) {
            toShore('suspend timeout after ' + Math.round(SUSPEND_MAX_MS / 60000) + 'min');
            statusFill = 'blue';

        } else if (loadNow.v <= st.suspendBase + RESUME_DELTA_W) {
            if (!st.resumeStart) st.resumeStart = now;
            if (now - st.resumeStart >= RESUME_MS) {
                st.resumeStart = 0;
                st.desired = 1;
                st.lastTransition = now;
                st.surgeStart = 0;
                st.loadExceedStart = 0;
                if (st.suspendPrev === 'burndown' && battV !== null && cvl !== null &&
                    battV.v > cvl.v - BURN_EXIT_DROP_V) {
                    st.state = 'burndown';
                    st.burnExitStart = 0;
                    st.burnCalmStart = 0;
                    transition = '-> BURNDOWN (resumed after suspend)';
                } else {
                    st.state = 'solar';
                    st.solarSince = now;
                    st.socEntry = soc.v;
                    st.lastBoostTs = now;
                    boostMsg = { payload: BOOST_V };   // re-ramp assist
                    transition = '-> SOLAR (resumed after suspend)';
                }
                statusFill = 'green';
                statusText = transition;
            } else {
                statusFill = 'yellow';
                statusText = 'SUSPEND | load ' + loadNow.v.toFixed(0) + 'W back at base — resume in ' +
                    Math.ceil((RESUME_MS - (now - st.resumeStart)) / 1000) + 's';
            }

        } else {
            st.resumeStart = 0;
            statusFill = 'blue';
            statusText = 'SUSPEND | load ' + loadNow.v.toFixed(0) + 'W (base ' +
                st.suspendBase.toFixed(0) + 'W) — timeout in ' +
                Math.ceil((SUSPEND_MAX_MS - (now - st.suspendStart)) / 60000) + 'min';
        }

    } else { // ---- SOLAR ----
        // A long stable stint proves the estimate is sound again
        if (st.backoffMs !== COOLDOWN_MS && now - st.solarSince >= STABLE_MS) {
            st.backoffMs = COOLDOWN_MS;
        }

        // Boost-drain grace (v3.5): a boosted probe charges the pack a
        // little ABOVE the target, so at handover (ceiling back at the
        // target) the MPPTs throttle to zero until the bus falls back
        // under it and the loads run from that surplus. That discharge is
        // the boost energy coming back out — a mini burn-down, not a
        // deficit. Once under the target the chargers re-ramp at a rate
        // set by the (initially tiny) margin, so the deficit clock also
        // waits out a settle window after entry. Emergency-SOC, SOC-drift
        // and fault exits stay live throughout.
        var draining = battV !== null && effCvl !== null &&
                       battV.v > effCvl + 0.01;
        var settling = draining || (now - st.solarSince) < SOLAR_SETTLE_MS;

        var dischargeAvg = battMean !== null ? -battMean : discharge;
        if (dischargeAvg > DISCHARGE_TOL_W && !settling) { if (!st.loadExceedStart) st.loadExceedStart = now; }
        else st.loadExceedStart = 0;
        if (discharge > SURGE_W && !draining) { if (!st.surgeStart) st.surgeStart = now; }
        else st.surgeStart = 0;

        // Heater-class load: hand it to shore, come back when it ends (v4.0)
        if (loadNow.v >= SUSPEND_LOAD_W) {
            if (!st.suspendTrigStart) { st.suspendTrigStart = now; st.suspendBase = loadAvg.v; }
        } else st.suspendTrigStart = 0;

        if (st.suspendTrigStart && now - st.suspendTrigStart >= SUSPEND_MS) {
            st.state = 'suspend';
            st.suspendPrev = 'solar';
            st.desired = 0;
            st.suspendStart = now;
            st.lastTransition = now;
            st.suspendTrigStart = 0;
            st.resumeStart = 0;
            st.loadExceedStart = 0;
            st.surgeStart = 0;
            boostMsg = { payload: 0 };
            transition = '-> SUSPEND (load ' + loadNow.v.toFixed(0) + 'W, base ' +
                st.suspendBase.toFixed(0) + 'W)';
            statusFill = 'blue';
            statusText = transition;

        } else if (feed.v === 0 && sinceTrans > FEEDBACK_GRACE_MS) {
            // Something re-accepted AC-in 1 despite our 30s re-asserts
            node.error('Solar Priority: Quattro re-accepted AC during solar mode — standing down');
            lockout();
            toShore('FAULT: AC re-accepted externally');
            statusFill = 'red';

        } else if (soc.v < MIN_SOC || soc.v < st.socEntry - SOC_DRIFT_MAX) {
            escalateBackoff();
            toShore('SOC ' + soc.v.toFixed(1) + '% (entry ' + st.socEntry.toFixed(1) + '%)');
            statusFill = 'blue';

        } else if (st.surgeStart && now - st.surgeStart >= SURGE_MS) {
            toShore('big load: batt -' + discharge.toFixed(0) + 'W, load ' + loadNow.v.toFixed(0) + 'W');
            statusFill = 'blue';

        } else if (st.loadExceedStart && now - st.loadExceedStart >= LOAD_EXCEED_MS &&
                   dayOk && !shoreMissing && soc.v >= MIN_SOC &&
                   battV !== null && cvl !== null &&
                   battV.v >= cvl.v - STALL_BURN_MIN_V) {
            // Ceiling stall (v4.1): the band is still full, so this deficit
            // is the MPPTs starved of margin, not the sun failing. Burn the
            // band into the loads instead of cycling shore — burn-down's
            // calm handover brings us back here once the chargers carry
            // the load, and its bottom exit (target - BURN_EXIT_DROP_V)
            // still hands off to probe/shore if the sun really is gone.
            // Not a failure: no backoff escalation.
            st.state = 'burndown';
            st.desired = 1;
            st.lastTransition = now;
            st.refillReady = false;
            st.harvestSince = 0;
            st.readySince = 0;
            st.burnReadySince = 0;
            st.burnExitStart = 0;
            st.burnCalmStart = 0;
            st.surgeStart = 0;
            st.loadExceedStart = 0;
            transition = '-> BURNDOWN (ceiling stall: batt avg -' + dischargeAvg.toFixed(0) +
                'W at ' + battV.v.toFixed(2) + 'V, PV ' + pvNow.toFixed(0) + 'W)';
            statusFill = 'green';
            statusText = transition;

        } else if (st.loadExceedStart && now - st.loadExceedStart >= LOAD_EXCEED_MS) {
            escalateBackoff();
            toShore('deficit: batt avg -' + dischargeAvg.toFixed(0) + 'W (now ' + batt.v.toFixed(0) + 'W)');
            statusFill = 'blue';

        } else if (st.loadExceedStart || st.surgeStart) {
            var left = st.surgeStart ?
                Math.ceil((SURGE_MS - (now - st.surgeStart)) / 1000) :
                Math.ceil((LOAD_EXCEED_MS - (now - st.loadExceedStart)) / 1000);
            statusFill = 'yellow';
            statusText = 'SOLAR! batt avg -' + dischargeAvg.toFixed(0) + 'W (now ' + batt.v.toFixed(0) +
                'W) PV ' + pvNow.toFixed(0) + 'W load ' + loadNow.v.toFixed(0) + 'W [shore in ' + left + 's]';

        } else {
            statusFill = 'green';
            statusText = (draining ? 'SOLAR drain +' + (battV.v - effCvl).toFixed(2) + 'V | PV ' : 'SOLAR | PV ') +
                pvNow.toFixed(0) + 'W batt ' + (batt.v >= 0 ? '+' : '') +
                batt.v.toFixed(0) + 'W load ' + loadNow.v.toFixed(0) + 'W SOC ' + soc.v.toFixed(1) + '%';
        }
    }
}

// ---- Command emission ----
// Send on change; while enabled, also re-assert every ASSERT_MS so a vebus
// restart or external write cannot leave the system diverged. When disabled,
// never re-assert (the user may control IgnoreAcIn1 manually).
var cmdMsg = null;
if (st.lastSent !== st.desired || (enabled && now - st.lastAssert >= ASSERT_MS)) {
    st.lastSent = st.desired;
    st.lastAssert = now;
    cmdMsg = { payload: st.desired };
}

flow.set('sp_st', st);
node.status({ fill: statusFill, shape: 'dot', text: statusText });

return [
    cmdMsg,
    transition ? { payload: transition, topic: 'solar-priority' } : null,
    boostMsg
];

initialize:
// Reset the state machine on every deploy: always start on shore.
// Enable / rated power are restored from the state file ~6s later.
// (Capacity measurements reset too — they are re-learned within minutes
// whenever the chargers run unthrottled.)
flow.set('sp_st', null);

func:
// Any uncaught error in the decision engine forces shore power
var st = flow.get('sp_st');
if (st && typeof st === 'object') {
    st.state = 'shore';
    st.desired = 0;
    st.lastSent = 0;
    st.lastAssert = Date.now();
    flow.set('sp_st', st);
}
var errText = (msg.error && msg.error.message) || 'unknown';
node.error('Solar Priority decision error — forcing shore: ' + errText);
node.status({ fill: 'red', shape: 'ring', text: 'error -> shore: ' + errText });
return { payload: 0 };

// Payload: first line = writable state dir (discovered by the shell,
// running as the same user as Node-RED), rest = saved JSON (may be empty)
var raw = String(msg.payload);
var nl = raw.indexOf('\n');
var dir = (nl >= 0 ? raw.slice(0, nl) : raw).trim();
var rest = nl >= 0 ? raw.slice(nl + 1) : '';
if (dir) flow.set('sp_state_dir', dir);

var s = {};
try { s = JSON.parse(rest); } catch (e) { }

var enabled = s.enabled === true;
var pRated = (typeof s.pRated === 'number' && s.pRated >= 100 && s.pRated <= 2500) ? s.pRated : 1800;

// Set flow context directly (don't depend on the switch echo), then push
// the values back into the VRM virtual switches so the dashboard matches.
// Plain payloads: the virtual switch expands them to its default writable
// path (State for the toggle, Dimming for the slider).
flow.set('sp_enabled', enabled);
flow.set('sp_p_rated', pRated);
flow.set('sp_restored', true);

node.status({
    fill: 'blue', shape: 'dot',
    text: (enabled ? 'ENABLED' : 'disabled') + ' | ' + pRated + 'W | ' + dir
});

return [
    { payload: enabled ? 1 : 0 },
    { payload: pRated }
];

initialize:
// Reset on every deploy: saves stay blocked until this deploy's
// discovery + restore have run (flow context survives redeploys).
flow.set('sp_restored', false);
flow.set('sp_state_dir', '');

func:
var n = (flow.get('sp_restore_retries') || 0) + 1;
if (n > 5) {
    node.status({ fill: 'red', shape: 'ring', text: 'gave up after 5 retries' });
    return null;
}
flow.set('sp_restore_retries', n);
node.status({ fill: 'yellow', shape: 'ring', text: 'switch push failed — retry ' + n + '/5 in 3s' });
return msg;

// Never save before restore has run — a startup switch echo would
// otherwise overwrite the state file with defaults.
if (flow.get('sp_restored') !== true) return null;

// Only save once the startup discovery has found a writable dir — never guess
var dir = flow.get('sp_state_dir');
if (!dir) return null;
msg.filename = dir + '/solar-priority-state.json';

var pRated = flow.get('sp_p_rated');
msg.payload = JSON.stringify({
    enabled: flow.get('sp_enabled') === true,
    pRated: (typeof pRated === 'number') ? pRated : 1800,
    savedAt: new Date().toISOString()
}, null, 2);

node.status({ fill: 'grey', shape: 'dot', text: 'saved ' + msg.filename });
return msg;

// dbus-recbms is boosting the MPPTs above the CVL right now.
var v = Number(msg.payload);
if (!isFinite(v)) return null;
flow.set('sp_boost_active', { v: v, ts: Date.now() });
node.status({ fill: v === 1 ? 'green' : 'grey', shape: 'dot',
              text: v === 1 ? 'BOOSTING' : 'idle' });
return null;

// 1 while the driver says the array has settled and the reading counts.
var v = Number(msg.payload);
if (!isFinite(v)) return null;
flow.set('sp_boost_window', { v: v, ts: Date.now() });
node.status({ fill: v === 1 ? 'yellow' : 'grey', shape: 'dot',
              text: v === 1 ? 'MEASURING' : 'closed' });
return null;

// CVL + any active boost. The engine compares battV against THIS, so a
// boost we asked for is not mistaken for a surplus.
var v = Number(msg.payload);
if (!isFinite(v) || v < 20 || v > 80) return null;
flow.set('sp_boost_eff', { v: v, ts: Date.now() });
node.status({ fill: 'blue', shape: 'dot', text: v.toFixed(2) + ' V' });
return null;

// dbus-recbms >= 1.4.0 verifies that systemcalc really applies the
// solar offset (it silently ignores it below GX access level Superuser).
// "" = verified in force; anything else is a human-readable fault.
// Surface it loudly: node.error() lands in the Node-RED log / debug
// sidebar; the driver also raises the battery's InternalFailure alarm to
// warning, so the GUI notifies and a VRM alarm rule can mail.
var txt = (msg.payload === null || msg.payload === undefined) ? '' : String(msg.payload).trim();
var prev = flow.get('sp_lead_fault') || '';
flow.set('sp_lead_fault', txt);
if (txt && txt !== prev) {
    node.error('Solar lead FAULT (dbus-recbms): ' + txt +
        ' -- MPPTs are NOT above the Quattro; boosts refused, harvest disabled until cleared');
    node.status({ fill: 'red', shape: 'ring', text: 'FAULT: ' + txt.slice(0, 60) });
} else if (!txt && prev) {
    node.warn('Solar lead restored: systemcalc offset verified in force again');
    node.status({ fill: 'green', shape: 'dot', text: 'lead verified' });
} else if (!txt) {
    node.status({ fill: 'green', shape: 'dot', text: 'lead verified' });
}
return null;

// Lead actually in force (V). 0 while the driver has the lead disabled
// or a lead fault is active -> there is no band below the target for
// harvest-and-burn to fill, so the engine disables harvest.
var v = Number(msg.payload);
if (!isFinite(v) || v < 0 || v > 1) return null;
flow.set('sp_lead', { v: v, ts: Date.now() });
node.status({ fill: v > 0.005 ? 'green' : 'grey', shape: 'dot', text: v.toFixed(2) + ' V' });
return null;
